<?php require __DIR__.'/bootstrap.php';$sent=false;if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$email=filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL);$message=trim($_POST['message']??'');if($email&&$message){$q=$pdo->prepare('INSERT INTO contact_messages(email,message,created_at) VALUES(?,?,NOW())');$q->execute([$email,$message]);$sent=true;}}site_header($pdo,'Contact'); ?><section class="page-intro"><span class="eyebrow">WE ARE HERE TO HELP</span><h1>Contact</h1><p><?=e(setting($pdo,'store_email','hello@example.com'))?> · <?=e(setting($pdo,'store_whatsapp',''))?></p></section><section class="section narrow"><?php if($sent): ?><div class="notice">Thank you. Your message has been received.</div><?php else: ?><form method="post" class="checkout-form"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><label>Email<input type="email" name="email" required></label><label>Message<textarea name="message" required></textarea></label><button class="button">SEND MESSAGE</button></form><?php endif; ?></section><?php site_footer($pdo); ?>
